head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[input > E > oneditkeyup]<br/>키보드에서 키를 눌렀다 놓았을 때 발생합니다.",
    "validation" : [
        "키보드에서 키를 눌렀다 놓았을 때 이벤트가 발생합니다.",
        "oldValue, newValue, keyCode를 포함한 JSON객체가 인자로 추가로 넘어옵니다."
    ]
}



scwin.wf_sample_onwframeload = function () {
    // 테스트 설명, 유효성 생성
    let wf_body_left = wf_sample.getObj("wf_body_left");
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
      // 기존 target 있으면 삭제
    if (typeof startcomp !== 'undefined') {
        startcomp.remove();
    }

    let eList = $c.gcm.createEList(["oneditkeyup"]);  

    $c.gcm.createBasicInput('', eList);
}
